<script setup lang="ts">
import {computed,ref} from "vue";
import {NButton,NInput,NSelect,NSlider,NSwitch,NTabs,NTabPane,NModal,NEmpty,NAlert,NPagination,NCollapse,NCollapseItem,NColorPicker,NSpin} from "naive-ui";
import {invoke,type WallpaperLibrary,type WallpaperOptions} from "../../bridge.ts";
import {siteMedia} from "../../wallpaper-media.ts";
import type {ControlStore} from "../control-types.ts";
import {useWallpaperWorkspace,type Selection,type SelectedEffect} from "../wallpaper/useWallpaperWorkspace.ts";
import MediaPreview from "../wallpaper/MediaPreview.vue";
const props=defineProps<{store:ControlStore}>();
const {progress,progressPercent,saved,tab,media,query,category,page,localSource,selection,draft,busy,loading,error,feed,categories,kind,selectedEffect,setEffect,select,cancel,load,localItems,action}=useWallpaperWorkspace(props.store);
const advanced=ref(false),subscription=ref(props.store.settings.catalogUrl),advancedBusy=ref(false),file=ref<HTMLInputElement>();
const active=computed(()=>props.store.settings.wallpaperId === "companion" ? (props.store.settings.mode === "floating" ? "系统桌面" : "小伴房间") : props.store.library.items.find(e=>e.definition.id===props.store.settings.wallpaperId)?.definition.title || "当前壁纸");
const companionStatus=computed(()=>!props.store.settings.companionEnabled ? "小伴已隐藏" : props.store.settings.mode === "floating" ? "小伴悬浮陪伴" : "小伴融入壁纸");
const current=computed(()=>selection.value?.source==='local'?selection.value.item.definition:null);
const title=computed(()=>selection.value?.source==='local'?selection.value.item.definition.title:selection.value?.item.title || '');
const cards=computed<Selection[]>(()=>tab.value==='online'?feed.items.map(item=>({source:'online',item})):localItems.value.map(item=>({source:'local',item})));
const cardId=(card:Selection)=>card.source==='local'?card.item.definition.id:card.item.id;
const cardTitle=(card:Selection)=>card.source==='local'?card.item.definition.title:card.item.title;
const cardKind=(card:Selection)=>card.source==='local'?card.item.definition.kind:card.item.media_type;
const sources=(card:Selection)=>card.source==='online'?siteMedia(card.item,props.store.settings.websiteUrl):{poster:card.item.coverUrl || (card.item.definition.kind==='image'?card.item.previewUrl || '':''),video:card.item.previewUrl || ''};
const preview=computed(()=>selection.value?sources(selection.value):{poster:'',video:''});
const effect=computed(()=>selectedEffect.value==='none'?null:draft.value.effects[selectedEffect.value as SelectedEffect & keyof typeof draft.value.effects]);
const types=[{label:'全部类型',value:''},{label:'图片',value:'image'},{label:'视频',value:'video'},{label:'互动动画',value:'canvas'}];
const fits=[{label:'铺满屏幕',value:'cover'},{label:'完整显示',value:'contain'},{label:'拉伸适配',value:'fill'}];
const effects=[{label:'无特效',value:'none'},{label:'下雨',value:'rain'},{label:'下雪',value:'snow'},{label:'萤火虫',value:'fireflies'}];
async function importMedia(){try {const id=await props.store.importMedia();if(id){tab.value='local';localSource.value='local';const item=props.store.library.items.find(e=>e.definition.id===id);if(item)select({source:'local',item});}}catch(e){props.store.notify(e,'error');}}
async function advancedAction(command:string,args?:Record<string,unknown>){advancedBusy.value=true;try{if(!props.store.desktop)throw new Error('请在桌面应用中使用订阅与清单');props.store.library=await invoke<WallpaperLibrary>(command,args);await props.store.refreshSettings();props.store.notify('壁纸库已更新','success');}catch(e){props.store.notify(e,'error');}finally{advancedBusy.value=false;}}
async function importJson(event:Event){const input=event.target as HTMLInputElement;const selected=input.files?.[0];if(!selected)return;try{if(selected.size>1024*1024)throw new Error('清单不能超过 1 MB');await advancedAction('import_wallpaper_catalog',{text:await selected.text()});}catch(e){props.store.notify(e,'error');}finally{input.value='';}}
async function restoreRoom(){if(busy.value)return;busy.value=true;try{await props.store.applyWallpaper("companion",props.store.settings.wallpaperOptions);}catch(e){props.store.notify(e,"error");}finally{busy.value=false;}}
async function refreshSubscription(){const url=props.store.library.source;if(!url){props.store.notify("尚未添加订阅，请先填写订阅地址","info");return;}await advancedAction("subscribe_wallpapers",{url});}
function setFit(value:string){if(busy.value)return;draft.value.fit=value as WallpaperOptions['fit'];}
</script>
<template>
<section class="ui-page" data-testid="wallpapers-page">
<header class="page-header"><div><h1>壁纸库</h1><p class="page-subtitle">挑选喜欢的画面，让桌面清爽一点。</p></div><NButton type="primary" data-testid="import-media" :disabled="busy" @click="importMedia">导入图片 / 视频</NButton></header>
<div class="surface desktop-overview"><div class="overview-icon">▧</div><div><span class="muted">当前桌面</span><h3>{{active}}</h3><p class="muted">主显示器 · {{companionStatus}} · {{store.settings.paused?'动画已暂停':'动画运行中'}}</p></div><NButton size="small" data-testid="restore-room" :disabled="busy" @click="restoreRoom">恢复小伴房间</NButton></div>
<NTabs v-model:value="tab" type="line" animated><NTabPane name="online" :disabled="busy"><template #tab>在线资源</template></NTabPane><NTabPane name="local" :disabled="busy"><template #tab>我的壁纸</template></NTabPane></NTabs>
<div class="toolbar"><NInput :disabled="busy" v-model:value="query" clearable placeholder="搜索壁纸名称" data-testid="wallpaper-search" @keyup.enter="page=1;load()"/><NSelect :disabled="busy" v-model:value="media" :options="tab==='online'?types.filter(type=>type.value!=='canvas'):types" aria-label="壁纸类型"/><NSelect :disabled="busy" v-if="tab==='online'" v-model:value="category" :options="[{label:'全部分类',value:''},...categories.map(c=>({label:c.name,value:c.id}))]" aria-label="分类"/><NSelect :disabled="busy" v-else v-model:value="localSource" :options="[{label:'全部来源',value:''},{label:'我的导入',value:'local'},{label:'内置壁纸',value:'builtin'},{label:'订阅壁纸',value:'subscription'}]" aria-label="本地来源"/><NButton :disabled="busy" v-if="tab==='online'" @click="page=1;load()">搜索</NButton><NButton v-else :disabled="busy" @click="advanced=true">订阅与清单</NButton></div>
<NAlert v-if="error" type="error" class="feed-alert">{{error}}<NButton size="small" @click="load">重试</NButton></NAlert>
<NAlert v-if="tab==='online'&&!store.desktop" type="info">在线资源需要桌面应用连接真实网站。浏览器预览可查看我的壁纸。</NAlert>
<div class="workspace" :class="{'has-selection':selection}"><div class="gallery-area"><NSpin :show="loading"><div class="gallery"><button v-for="card in cards" :key="card.source+cardId(card)" class="wallpaper-card" :disabled="busy" :class="{selected:selection&&cardId(selection)===cardId(card)&&selection.source===card.source}" :data-testid="'wallpaper-card-'+cardId(card)" @click="select(card)"><div class="card-cover"><MediaPreview :kind="cardKind(card)" :source="sources(card).video" :poster="sources(card).poster" :title="cardTitle(card)"/><span class="type-badge">{{cardKind(card)==='video'?'视频':cardKind(card)==='canvas'?'动画':'图片'}}</span></div><div class="card-info"><strong>{{cardTitle(card)}}</strong><span class="muted">{{card.source==='online'?card.item.author.name:card.item.installed?'本地可用':'订阅资源'}}</span></div></button></div><NEmpty v-if="!cards.length&&!loading" :description="tab==='online'?'暂无匹配的在线资源':'还没有这一类壁纸'" class="empty-state"/></NSpin><div v-if="tab==='online'" class="pagination"><span class="muted">共 {{feed.total}} 张</span><NPagination :disabled="busy" :page="page" :page-count="page+(feed.has_more?1:0)" @update:page="page=$event"/></div><p v-else class="gallery-note muted">导入会保存文件副本；下载完成后可离线使用。</p></div>
<aside v-if="selection" class="surface inspector" data-testid="wallpaper-inspector"><div class="inspector-heading"><span class="muted">预览与设置</span><NButton text data-testid="cancel-selection" :disabled="busy" @click="cancel">取消选择</NButton></div><div class="inspector-preview"><MediaPreview :key="selection.source+cardId(selection)" :kind="kind || ''" :source="preview.video" :poster="preview.poster" :title="title" controls :fit="draft.fit" :rate="draft.playbackRate" :effects="draft.effects" :paused="store.settings.paused" :fps="store.settings.fps"/></div><h2>{{title}}</h2><p class="muted">{{selection.source==='local'?selection.item.definition.description:selection.item.description}}</p><div class="draft-note">此处修改仅用于预览，点击应用后才更换桌面。</div>
<div v-if="kind!=='canvas'" class="field"><label>画面适配</label><NSelect :disabled="busy" :value="draft.fit" :options="fits" data-testid="wallpaper-fit" @update:value="setFit"/></div><div v-if="kind==='video'" class="field"><label>播放速度 <span>{{draft.playbackRate}}×</span></label><NSlider :disabled="busy" v-model:value="draft.playbackRate" :min="0.25" :max="2" :step="0.25"/><small class="muted">静音循环播放</small></div>
<div class="field"><label>图片特效</label><NSelect :value="selectedEffect" :options="effects" :disabled="busy || kind!=='image'" data-testid="wallpaper-effect" @update:value="setEffect"/><small v-if="kind!=='image'" class="muted">特效只支持图片，参数会保留。</small></div><template v-if="kind==='image'&&effect"><div class="field"><label>强度 <span>{{Math.round(effect.intensity*100)}}%</span></label><NSlider :disabled="busy" v-model:value="effect.intensity" :min="0" :max="1" :step="0.05"/></div><div class="field"><label>速度 <span>{{effect.speed}}×</span></label><NSlider :disabled="busy" v-model:value="effect.speed" :min="0.25" :max="3" :step="0.25"/></div></template>
<NCollapse v-if="current?.controls?.length"><NCollapseItem title="动画参数" name="controls"><div v-for="control in current.controls" :key="control.key" class="field"><label>{{control.label}}</label><NSlider :disabled="busy" v-if="control.type==='range'" :value="Number(draft.values[control.key])" :min="control.min" :max="control.max" :step="control.step" @update:value="draft.values[control.key]=$event"/><NSwitch :disabled="busy" v-else-if="control.type==='boolean'" :value="Boolean(draft.values[control.key])" @update:value="draft.values[control.key]=$event"/><NColorPicker :disabled="busy" v-else-if="control.type==='color'" :value="String(draft.values[control.key])" :show-alpha="false" @update:value="draft.values[control.key]=$event"/><NSelect :disabled="busy" v-else :value="String(draft.values[control.key])" :options="(control.options||[]).map(value=>({label:value,value}))" @update:value="draft.values[control.key]=$event"/></div></NCollapseItem></NCollapse>
<div v-if="busy" class="download-feedback" role="status" data-testid="wallpaper-progress"><span>{{progressPercent===null ? "正在准备壁纸文件…" : progressPercent>=100 ? "下载完成，正在校验 / 应用…" : `正在下载 ${progressPercent}%`}}</span><progress v-if="progress" max="100" :value="progressPercent || 0"/><progress v-else max="100"/></div><div class="actions"><NButton v-if="selection.source==='online'" block :loading="busy" :disabled="saved || busy" data-testid="save-wallpaper" @click="action(false)">{{saved?'已保存到我的壁纸':'保存到我的壁纸'}}</NButton><NButton v-if="kind==='canvas'" block :disabled="busy" @click="action(true,true)">独立窗口预览</NButton><NButton type="primary" block :loading="busy" data-testid="apply-wallpaper" :disabled="busy" @click="action(true)">应用到桌面</NButton></div></aside>
<aside v-else class="surface inspector-placeholder"><div>▧</div><h3>选择一张壁纸</h3><p class="muted">在右侧查看预览、设置画面与特效。</p></aside></div>
<NModal v-model:show="advanced" preset="card" title="订阅与清单" class="advanced-modal" style="width:min(520px,90vw)"><p class="muted">订阅 HTTPS 清单，或导入已有的 JSON 壁纸清单。</p><div class="field"><label>订阅地址</label><NInput :disabled="busy" v-model:value="subscription" placeholder="https://…/wallpapers.json"/></div><div class="advanced-actions"><NButton :loading="advancedBusy" type="primary" @click="advancedAction('subscribe_wallpapers',{url:subscription})">添加订阅</NButton><NButton data-testid="refresh-subscription" :disabled="advancedBusy" @click="refreshSubscription">刷新订阅</NButton><NButton @click="file?.click()">导入 JSON</NButton></div><input ref="file" type="file" accept=".json,application/json" hidden @change="importJson"/></NModal>
</section>
</template>
<style scoped>
.desktop-overview{display:flex;align-items:center;gap:15px;padding:20px;margin:0 0 20px}.desktop-overview h3{margin:3px 0;font-size:17px}.desktop-overview p{margin:4px 0}.desktop-overview>.n-button{margin-left:auto}.overview-icon{width:48px;height:48px;border-radius:12px;display:grid;place-items:center;background:#e7f1ff;font-size:28px;color:#3673cf}.toolbar{display:flex;gap:10px;margin:12px 0 20px}.toolbar>.n-input{flex:1}.toolbar>.n-select{width:145px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:20px}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.wallpaper-card{text-align:left;padding:0;border:1px solid #e1e7f0;background:white;border-radius:12px;overflow:hidden;cursor:pointer;color:#25334a;transition:border-color .15s,box-shadow .15s}.wallpaper-card:hover{border-color:#a7c6ef;box-shadow:0 4px 14px #2760a210}.wallpaper-card.selected{border:2px solid #367ee5;box-shadow:0 0 0 3px #367ee51a}.card-cover{aspect-ratio:16/10;position:relative}.type-badge{position:absolute;right:8px;bottom:8px;background:#142136b0;color:white;border-radius:5px;padding:2px 6px;font-size:11px}.card-info{padding:12px;display:grid;gap:5px}.card-info strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.card-info span{font-size:11px}.inspector{padding:18px;align-self:start;position:sticky;top:0}.inspector-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;font-size:12px}.inspector-preview{aspect-ratio:16/10;border-radius:9px;overflow:hidden}.inspector h2{font-size:18px;margin:16px 0 8px}.inspector>p{font-size:12px}.draft-note{background:#edf5ff;color:#5176a5;border-radius:7px;padding:9px;font-size:11px;margin:14px 0}.field{margin:16px 0}.field>label{display:flex;justify-content:space-between;font-size:12px;font-weight:600;margin-bottom:8px}.field small{font-size:11px}.download-feedback{display:grid;gap:8px;margin-top:16px;color:#5176a5;font-size:12px}.download-feedback progress{width:100%;height:6px;accent-color:#367ee5}.actions{display:grid;gap:9px;margin-top:22px}.inspector-placeholder{padding:60px 20px;text-align:center;align-self:start}.inspector-placeholder>div{font-size:40px;color:#9bb5d5}.inspector-placeholder p{font-size:12px}.pagination{display:flex;justify-content:space-between;align-items:center;margin-top:20px}.gallery-note{font-size:12px;margin-top:20px}.feed-alert{margin-bottom:16px}.advanced-actions{display:flex;gap:8px}@media(max-width:1100px){.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.workspace{grid-template-columns:minmax(0,1fr) 280px}}@media(max-width:780px){.workspace{grid-template-columns:1fr}.inspector{position:static}.toolbar{flex-wrap:wrap}.toolbar>.n-input{flex-basis:100%}.inspector-placeholder{display:none}}
</style>
